import{_ as e,C as s,o as r,c as d,j as t,a as i,E as n,a5 as c}from"./chunks/framework.B1qnvv14.js";const v=JSON.parse('{"title":"Requisitos e ambiente","description":"","frontmatter":{"title":"Requisitos e ambiente"},"headers":[],"relativePath":"requisitos.md","filePath":"requisitos.md","lastUpdated":1793391883000}'),l={name:"requisitos.md"};function p(m,o,h,u,g,b){const a=s("CopyOrDownloadAsMarkdownButtons");return r(),d("div",null,[o[0]||(o[0]=t("h1",{id:"requisitos-e-ambiente",tabindex:"-1"},[i("Requisitos e ambiente "),t("a",{class:"header-anchor",href:"#requisitos-e-ambiente","aria-label":'Permalink to "Requisitos e ambiente"'},"​")],-1)),n(a),o[1]||(o[1]=c(`<p>O automacli precisa de pouco para funcionar e aproveita o que a máquina oferece a mais. Nada além de git e Docker é obrigatório; cada recurso opcional melhora algo e, quando falta, o automacli usa a alternativa sozinho.</p><p>Para ver o que a sua máquina tem e o que o automacli vai fazer com isso:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minha-org/minha-api</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # avalia a estratégia de clone com o repo base</span></span></code></pre></div><h2 id="obrigatorio" tabindex="-1">Obrigatório <a class="header-anchor" href="#obrigatorio" aria-label="Permalink to &quot;Obrigatório&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Para quê</th></tr></thead><tbody><tr><td><strong>git</strong></td><td>Clonar e acompanhar as branches.</td></tr><tr><td><strong>Docker com Compose v2.24 ou superior</strong></td><td>Subir as stacks. O override gerado usa a tag <code>!override</code>, que o Compose só aceita a partir da 2.24.</td></tr></tbody></table><p>O executável dos releases traz o próprio Node.js; para rodar do código-fonte é preciso Node 22 ou superior.</p><h2 id="opcional" tabindex="-1">Opcional <a class="header-anchor" href="#opcional" aria-label="Permalink to &quot;Opcional&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>O que melhora</th><th>Sem ele</th></tr></thead><tbody><tr><td><strong>btrfs</strong> no diretório das tasks</td><td>Clones por snapshot (instantâneos) ou reflink; uso real de disco no monitor</td><td>Clones por <code>git clone --reference</code>; o monitor mostra só o tamanho aparente</td></tr><tr><td><strong>XFS ou APFS</strong> (macOS)</td><td>Clones por reflink</td><td>Idem</td></tr><tr><td><strong>btrfs-progs</strong> (<code>btrfs</code>)</td><td>Snapshot e medição de disco</td><td>Reflink continua funcionando</td></tr><tr><td>Montagem com <code>user_subvol_rm_allowed</code></td><td>Apagar uma task por snapshot devolve o disco na hora</td><td>A task é movida para <code>.lixeira/</code> (instantâneo) e apagada em segundo plano; o disco volta em alguns minutos</td></tr><tr><td><strong>systemd</strong></td><td>Isolamento de CPU e memória por slot; monitor como serviço</td><td>Sem isolamento; monitor iniciado à mão</td></tr><tr><td><strong>journalctl</strong></td><td><code>automacli oom</code> identifica mortes pelo systemd-oomd e pelo kernel, com o motivo</td><td><code>automacli oom</code> usa só o que o Docker registra</td></tr><tr><td><strong>notify-send</strong></td><td>Aviso de desktop quando um serviço morre por falta de memória</td><td>Aviso só no log do monitor</td></tr><tr><td><strong>wl-copy, xclip, xsel, pbcopy</strong></td><td>O <code>clone</code> copia o <code>cd</code> da task</td><td>O <code>clone</code> imprime o <code>cd</code></td></tr></tbody></table><h2 id="como-as-tasks-sao-criadas" tabindex="-1">Como as tasks são criadas <a class="header-anchor" href="#como-as-tasks-sao-criadas" aria-label="Permalink to &quot;Como as tasks são criadas&quot;">​</a></h2><p>O <code>clone</code> cria a task a partir do <strong>repo base</strong> (uma task mantida na branch principal) com a melhor estratégia disponível, caindo para a seguinte se uma falhar:</p><table tabindex="0"><thead><tr><th>Estratégia</th><th>Exige</th><th>Tempo em um repo de 9 GB e 875 mil arquivos</th><th>Traz <code>node_modules</code> instalado</th></tr></thead><tbody><tr><td><strong>snapshot</strong></td><td>btrfs, btrfs-progs e repo base convertido em subvolume</td><td>&lt; 1 s</td><td>sim</td></tr><tr><td><strong>reflink</strong></td><td>btrfs, XFS ou APFS</td><td>~40 s</td><td>sim</td></tr><tr><td><strong>git clone --reference</strong></td><td>nada</td><td>segundos (reaproveita os objetos git do base, sem rede para o histórico)</td><td><strong>não</strong>: instale depois (ou use um template para isso)</td></tr><tr><td><strong>git clone</strong></td><td>nada</td><td>depende da rede</td><td>não</td></tr></tbody></table><p>A estratégia é escolhida pelo <code>cloneStrategy</code> do <code>config.json</code> (<code>auto</code> por padrão; o <code>automacli init</code> pergunta) e pode ser escolhida por clone com <code>automacli clone … --strategy reflink</code>; se ela não estiver disponível ou falhar, o automacli cai para a próxima.</p><p>Para habilitar o snapshot, converta o repo base uma vez por repositório:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minha-org/minha-api</span></span></code></pre></div><p>A conversão copia a árvore por reflink para um subvolume novo e troca os dois: não gasta disco, mantém o compartilhamento com as tasks já existentes e leva cerca de um minuto. Não rode com um clone em andamento.</p><h3 id="snapshots-e-backups" tabindex="-1">Snapshots e backups <a class="header-anchor" href="#snapshots-e-backups" aria-label="Permalink to &quot;Snapshots e backups&quot;">​</a></h3><p>Um snapshot do <code>/home</code> (Timeshift, snapper, <code>btrfs send</code>) <strong>não inclui</strong> subvolumes aninhados. Com o repo base convertido e as tasks criadas por snapshot, elas ficam fora desses backups. Para a maioria das pessoas isso é o desejado, já que tasks são descartáveis, mas vale saber.</p><p>Ferramentas que param na fronteira do sistema de arquivos (<code>du -x</code>, <code>find -xdev</code>, <code>rsync -x</code>) tratam cada subvolume como outro disco e não entram nele.</p><h2 id="sistemas-operacionais" tabindex="-1">Sistemas operacionais <a class="header-anchor" href="#sistemas-operacionais" aria-label="Permalink to &quot;Sistemas operacionais&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Situação</th></tr></thead><tbody><tr><td><strong>Linux</strong> (qualquer distribuição)</td><td>Suportado. Executável, <code>.deb</code>, <code>.rpm</code> e <code>PKGBUILD</code> nos releases.</td></tr><tr><td><strong>macOS</strong></td><td>O código roda (reflink pelo APFS, sem systemd); ainda não há executável nos releases.</td></tr><tr><td><strong>Windows</strong></td><td>Não suportado.</td></tr></tbody></table>`,20))])}const f=e(l,[["render",p]]);export{v as __pageData,f as default};
